int read_from_socket(int s, void* arg, int* len) {
    int header;
    int bytes_read;

    // Read the header to determine the length of the data
    if ((bytes_read = read(s, &header, sizeof(int))) <= 0) {
        return -1;
    }

    // Update the length
    *len = header;

    // If length is greater than zero, read the actual data
    if (*len > 0) {
        if ((bytes_read = read(s, arg, *len)) <= 0) {
            return -1;
        }
    }

    // Return the type of data read (here using header as type)
    return header;
}

