int read_socket_data(int s, void *arg, int *len) {
    int data_type;
    int bytes_read;

    // Read the header to determine the length of the incoming data
    if (recv(s, &data_type, sizeof(int), 0) != sizeof(int)) {
        return -1;
    }

    if (recv(s, len, sizeof(int), 0) != sizeof(int)) {
        return -1;
    }

    // Check if the length is valid
    if (*len <= 0) {
        return -1;
    }

    // Read the actual data into the buffer
    bytes_read = recv(s, arg, *len, 0);
    if (bytes_read < 0) {
        return -1;
    }

    *len = bytes_read;
    return data_type;
}

